#include <stdio.h>
#include <stddef.h>

int sum_index(const int *values, size_t count) {
    int sum = 0;
    for (size_t i = 0; i < count; i++) sum += values[i];
    return sum;
}

int sum_pointer(const int *values, size_t count) {
    int sum = 0;
    const int *end = values + count;          /* one past: compare, never read. */
    for (const int *p = values; p < end; p++) sum += *p;
    return sum;
}

int main(void) {
    int v[] = {4, 8, 15, 16};
    printf("%d %d\n", sum_index(v, 4), sum_pointer(v, 4));   /* 43 43. */
    ptrdiff_t gap = &v[3] - &v[1];            /* 2 elements. */
    printf("%td\n", gap);
    return 0;
}
```

